#!/usr/bin/env python
"""
build_rag_evaluation_project.py

Single-cell Google Colab / local script that generates the COMPLETE
"RAG Evaluation & Benchmarking System" project on disk and packages it
into a downloadable ZIP archive.

Usage (Colab or local terminal):
    python build_rag_evaluation_project.py

After running, you will have:
    ./rag-evaluation-benchmark/            (the full project directory)
    ./rag-evaluation-benchmark.zip         (a zip of the same project)

Every file written by this script is complete, real, executable source
code (base64-embedded below purely to make embedding robust against
quoting/escaping issues with nested triple-quoted docstrings in the
generated files themselves) -- there are no placeholders, no TODOs, and
no pseudocode. Decoding the base64 payloads reproduces the exact project
files byte-for-byte.
"""

