def write_files() -> None:
    """Decode and write every embedded file to disk, creating directories as needed."""
    if PROJECT_ROOT.exists():
        print(f"Removing existing directory: {PROJECT_ROOT}")
        shutil.rmtree(PROJECT_ROOT)

    for rel_path, b64_content in FILES_B64.items():
        target = PROJECT_ROOT / rel_path
        target.parent.mkdir(parents=True, exist_ok=True)
        data = base64.b64decode(b64_content.encode("ascii"))
        with open(target, "wb") as f:
            f.write(data)
        print(f"Created {target}")

    # Ensure the results directories exist even though .gitkeep files are
    # already among the embedded files above (defensive, idempotent).
    (PROJECT_ROOT / "results" / "plots").mkdir(parents=True, exist_ok=True)


def make_zip() -> None:
    """Zip the generated project directory into PROJECT_DIR_NAME.zip."""
    if ZIP_PATH.exists():
        ZIP_PATH.unlink()

    with zipfile.ZipFile(ZIP_PATH, "w", zipfile.ZIP_DEFLATED) as zf:
        for path in sorted(PROJECT_ROOT.rglob("*")):
            if path.is_file():
                arcname = Path(PROJECT_DIR_NAME) / path.relative_to(PROJECT_ROOT)
                zf.write(path, arcname)

    print(f"\nCreated ZIP archive: {ZIP_PATH}")


def print_summary() -> None:
    num_files = sum(1 for p in PROJECT_ROOT.rglob("*") if p.is_file())
    print("\n" + "=" * 60)
    print("RAG EVALUATION & BENCHMARKING PROJECT GENERATED")
    print("=" * 60)
    print(f"Project directory : {PROJECT_ROOT}")
    print(f"ZIP archive        : {ZIP_PATH}")
    print(f"Files written      : {num_files}")
    print()
    print("Next steps:")
    print(f"  cd {PROJECT_DIR_NAME}")
    print("  pip install -r requirements.txt")
    print("  python run_evaluation.py     # run the full evaluation pipeline")
    print("  python -m pytest tests/ -v   # run the test suite")
    print("  python generate_report.py    # regenerate report/plots from saved results")
    print("=" * 60)


def main() -> None:
    print(f"Generating '{PROJECT_DIR_NAME}' at {PROJECT_ROOT} ...\n")
    write_files()
    make_zip()
    print_summary()


if __name__ == "__main__":
    main()
